class BinaryDataProcessor:
    """
    A class used to process binary data, including cleaning, analyzing,
    and converting binary strings.
    """

    def __init__(self, binary_string):
        self.binary_string = binary_string
        self.clean_non_binary_chars()

    def clean_non_binary_chars(self):
        self.binary_string = ''.join(ch for ch in self.binary_string if ch in '01')

    def calculate_binary_info(self):
        length = len(self.binary_string)
        if length == 0:
            return {'Zeroes': 0.0, 'Ones': 0.0, 'Bit length': 0}
        zeroes = self.binary_string.count('0')
        ones = self.binary_string.count('1')
        return {
            'Zeroes': zeroes / length,
            'Ones': ones / length,
            'Bit length': length,
        }

    def convert_to_ascii(self):
        chars = []
        for i in range(0, len(self.binary_string), 8):
            byte_str = self.binary_string[i:i + 8]
            if byte_str:
                chars.append(chr(int(byte_str, 2)))
        return ''.join(chars)

    def convert_to_utf8(self):
        byte_values = []
        for i in range(0, len(self.binary_string), 8):
            byte_str = self.binary_string[i:i + 8]
            if byte_str:
                byte_values.append(int(byte_str, 2))
        return bytes(byte_values).decode('utf-8')
