import random
from collections import deque

class MahjongConnect:
    """
    MahjongConnect is a class representing a game board for Mahjong Connect with features like creating the board, checking valid moves, finding paths, removing icons, and checking if the game is over.
    """

    def __init__(self, BOARD_SIZE, ICONS):
        self.BOARD_SIZE = BOARD_SIZE
        self.ICONS = ICONS
        self.board = self.create_board()

    def create_board(self):
        return [[random.choice(self.ICONS) for _ in range(self.BOARD_SIZE[1])] for _ in range(self.BOARD_SIZE[0])]

    def is_valid_move(self, pos1, pos2):
        x1, y1 = pos1
        x2, y2 = pos2
        rows, cols = self.BOARD_SIZE
        if not (0 <= x1 < rows and 0 <= y1 < cols and 0 <= x2 < rows and 0 <= y2 < cols):
            return False
        if pos1 == pos2:
            return False
        if self.board[x1][y1] == ' ' or self.board[x2][y2] == ' ':
            return False
        if self.board[x1][y1] != self.board[x2][y2]:
            return False
        return self.has_path(pos1, pos2)

    def has_path(self, pos1, pos2):
        rows, cols = self.BOARD_SIZE
        pr, pc = rows + 2, cols + 2
        start = (pos1[0] + 1, pos1[1] + 1)
        end = (pos2[0] + 1, pos2[1] + 1)

        if start == end:
            return True

        dirs = [(-1, 0), (0, 1), (1, 0), (0, -1)]

        def is_empty(x, y):
            if x == 0 or x == pr - 1 or y == 0 or y == pc - 1:
                return True
            return self.board[x - 1][y - 1] == ' '

        queue = deque()
        visited = set()

        for d in range(4):
            dx, dy = dirs[d]
            nx, ny = start[0] + dx, start[1] + dy
            if 0 <= nx < pr and 0 <= ny < pc:
                if (nx, ny) == end or is_empty(nx, ny):
                    state = (nx, ny, d, 0)
                    queue.append(state)
                    visited.add(state)

        while queue:
            x, y, d, turns = queue.popleft()
            if (x, y) == end:
                return True
            for nd in range(4):
                dx, dy = dirs[nd]
                nx, ny = x + dx, y + dy
                if 0 <= nx < pr and 0 <= ny < pc:
                    if (nx, ny) == end or is_empty(nx, ny):
                        new_turns = turns + (1 if nd != d else 0)
                        if new_turns <= 2:
                            state = (nx, ny, nd, new_turns)
                            if state not in visited:
                                visited.add(state)
                                queue.append(state)
        return False

    def remove_icons(self, pos1, pos2):
        x1, y1 = pos1
        x2, y2 = pos2
        self.board[x1][y1] = ' '
        self.board[x2][y2] = ' '

    def is_game_over(self):
        for row in self.board:
            if any(icon != ' ' for icon in row):
                return False
        return True
