class TicTacToe:
    def __init__(self, N=3):
        self.N = N
        self.board = [[' ' for _ in range(N)] for _ in range(N)]
        self.current_player = 'X'

    def make_move(self, row, col):
        if not (0 <= row < self.N and 0 <= col < self.N):
            return False
        if self.board[row][col] != ' ':
            return False

        self.board[row][col] = self.current_player
        self.current_player = 'O' if self.current_player == 'X' else 'X'
        return True

    def check_winner(self):
        n = self.N

        for row in self.board:
            if row[0] != ' ' and all(cell == row[0] for cell in row):
                return row[0]

        for col in range(n):
            first = self.board[0][col]
            if first != ' ' and all(self.board[row][col] == first for row in range(n)):
                return first

        first = self.board[0][0]
        if first != ' ' and all(self.board[i][i] == first for i in range(n)):
            return first

        first = self.board[0][n - 1]
        if first != ' ' and all(self.board[i][n - 1 - i] == first for i in range(n)):
            return first

        return None

    def is_board_full(self):
        return all(cell != ' ' for row in self.board for cell in row)
