class BigNumCalculator:
    """
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    """

    @staticmethod
    def _parse(num):
        num = num.strip()
        if not num:
            return 1, "0"

        sign = 1
        if num[0] == '-':
            sign = -1
            num = num[1:]
        elif num[0] == '+':
            num = num[1:]

        num = num.lstrip('0') or '0'
        if num == '0':
            sign = 1
        return sign, num

    @staticmethod
    def _compare_abs(a, b):
        if len(a) != len(b):
            return -1 if len(a) < len(b) else 1
        if a == b:
            return 0
        return -1 if a < b else 1

    @staticmethod
    def _add_abs(a, b):
        i, j = len(a) - 1, len(b) - 1
        carry = 0
        result = []

