from datetime import datetime
import numpy as np


class MovieBookingSystem:
    """
    this is a class as movie booking system, which allows to add movies, book tickets and check the available movies within a given time range.
    """

    def __init__(self):
        """
        Initialize movies contains the information about movies
        """
        self.movies = []

    def add_movie(self, name, price, start_time, end_time, n):
        """
        Add a new movie into self.movies
        """
        movie = {
            'name': name,
            'price': price,
            'start_time': datetime.strptime(start_time, '%H:%M'),
            'end_time': datetime.strptime(end_time, '%H:%M'),
            'seats': np.zeros((n, n))
        }
        self.movies.append(movie)

    def book_ticket(self, name, seats_to_book):
        """
        Book tickets for a movie.
        """
        for movie in self.movies:
            if movie['name'] == name:
                seats = movie['seats']
                rows, cols = seats.shape
                requested = set()

                for seat in seats_to_book:
                    if not isinstance(seat, (tuple, list)) or len(seat) != 2:
                        return 'Booking failed.'

                    row, col = seat

                    if row < 0 or row >= rows or col < 0 or col >= cols:
                        return 'Booking failed.'

                    if (row, col) in requested:
                        return 'Booking failed.'

                    requested.add((row, col))

                    if seats[row, col] != 0:
                        return 'Booking failed.'

                for row, col in requested:
                    seats[row, col] = 1

                return 'Booking success.'

        return 'Movie not found.'

    def available_movies(self, start_time, end_time):
        """
        Get a list of available movies within the specified time range.
        """
        start = datetime.strptime(start_time, '%H:%M')
        end = datetime.strptime(end_time, '%H:%M')

        available_movies = []

        for movie in self.movies:
            if start <= movie['start_time'] and movie['end_time'] <= end:
                available_movies.append(movie['name'])

        return available_movies
