class NumberWordFormatter:
    """
    This is a class that provides to convert numbers into their corresponding English word representation, including handling the conversion of both the integer and decimal parts, and incorporating appropriate connectors and units.
    """

    def __init__(self):
        """
        Initialize NumberWordFormatter object.
        """
        self.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        self.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        self.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        self.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        self.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]

    def format(self, x):
        """
        Converts a number into words format
        :param x: int or float, the number to be converted into words format
        :return: str, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format(123456)
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        """
        if isinstance(x, str):
            return self.format_string(x)
        if x < 0:
            return "MINUS " + self.format(-x)
        if x == 0:
            return "ZERO ONLY"
        if isinstance(x, float):
            if x.is_integer():
                return self.format(int(x))
            return self.format_string(str(x))
        return self.format_string(str(x))

    def format_string(self, x):
        """
        Converts a string representation of a number into words format
        :param x: str, the string representation of a number
        :return: str, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format_string("123456")
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        """
        x = str(x).strip()
        if x == "":
            return "ZERO ONLY"
        if x.startswith("-"):
            return "MINUS " + self.format_string(x[1:])
        if x.startswith("+"):
            x = x[1:]
        if "." in x:
            integer_part, decimal_part = x.split(".", 1)
            if integer_part == "":
                integer_part = "0"
            if decimal_part == "":
                return self.format_string(integer_part)
            if decimal_part.strip("0") == "":
                return self.format_string(integer_part)

            int_part = integer_part.lstrip("0")
            if int_part == "":
                int_words = "ZERO"
            else:
                groups = []
                temp = int_part
                while temp:
                    groups.append(temp[-3:])
                    temp = temp[:-3]
                words = []
                for i in range(len(groups) - 1, -1, -1):
                    group_words = self.trans_three(groups[i])
                    if group_words:
                        unit = self.parse_more(i)
                        if unit:
                            words.append(group_words + " " + unit)
                        else:
                            words.append(group_words)
                int_words = " ".join(words)

            dec_words_list = []
            for ch in decimal_part:
                if ch.isdigit():
                    if ch == '0':
                        dec_words_list.append("ZERO")
                    else:
                        dec_words_list.append(self.NUMBER[int(ch)])
            dec_words = " ".join(dec_words_list)

            if int_words == "ZERO":
                if dec_words:
                    return "ZERO POINT " + dec_words + " ONLY"
                else:
                    return "ZERO ONLY"
            if dec_words:
                return int_words + " POINT " + dec_words + " ONLY"
            else:
                return int_words + " ONLY"
        else:
            int_part = x.lstrip("0")
            if int_part == "":
                return "ZERO ONLY"
            groups = []
            temp = int_part
            while temp:
                groups.append(temp[-3:])
                temp = temp[:-3]
            words = []
            for i in range(len(groups) - 1, -1, -1):
                group_words = self.trans_three(groups[i])
                if group_words:
                    unit = self.parse_more(i)
                    if unit:
                        words.append(group_words + " " + unit)
                    else:
                        words.append(group_words)
            return " ".join(words) + " ONLY"

    def trans_two(self, s):
        """
        Converts a two-digit number into words format
        :param s: str, the two-digit number
        :return: str, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_two("23")
        "TWENTY THREE"
        """
        if not s:
            return ""
        s = str(s).strip()
        if len(s) == 1:
            if s == "0":
                return ""
            return self.NUMBER[int(s)]
        if len(s) > 2:
            s = s[-2:]
        if s == "00":
            return ""
        if s[0] == '1':
            return self.NUMBER_TEEN[int(s[1])]
        tens = self.NUMBER_TEN[int(s[0]) - 1] if s[0] != '0' else ""
        ones = self.NUMBER[int(s[1])] if s[1] != '0' else ""
        if tens and ones:
            return tens + " " + ones
        return tens or ones

    def trans_three(self, s):
        """
        Converts a three-digit number into words format
        :param s: str, the three-digit number
        :return: str, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_three("123")
        "ONE HUNDRED AND TWENTY THREE"
        """
        if not s:
            return ""
        s = str(s).strip()
        if len(s) > 3:
            s = s[-3:]
        if len(s) == 1:
            return self.trans_two(s)
        if len(s) == 2:
            return self.trans_two(s)
        if s == "000":
            return ""
        if s[0] == '0':
            return self.trans_two(s[1:])
        hundreds = self.NUMBER[int(s[0])] + " HUNDRED"
        rest = s[1:]
        rest_words = self.trans_two(rest)
        if rest_words:
            return hundreds + " AND " + rest_words
        else:
            return hundreds

    def parse_more(self, i):
        """
        Parses the thousand/million/billion suffix based on the index
        :param i: int, the index representing the magnitude (thousand, million, billion)
        :return: str, the corresponding suffix for the magnitude
        >>> formatter = NumberWordFormatter()
        >>> formatter.parse_more(1)
        "THOUSAND"
        """
        if i < len(self.NUMBER_MORE):
            return self.NUMBER_MORE[i]
        more = ["", "THOUSAND", "MILLION", "BILLION", "TRILLION", "QUADRILLION", "QUINTILLION"]
        if i < len(more):
            return more[i]
        return ""
