        """
        dish_name = dish.get("dish")
        count = dish.get("count")

        if dish_name is None or count is None or count <= 0:
            return False

        for menu_dish in self.menu:
            if menu_dish.get("dish") == dish_name:
                if menu_dish.get("count", 0) >= count:
                    self.selected_dishes.append({
                        "dish": dish_name,
                        "count": count,
                        "price": dish.get("price", menu_dish.get("price"))
                    })
                    menu_dish["count"] -= count
                    return True
                return False

        return False

    def calculate_total(self):
        """
        Calculate the total price of dishes that have been ordered. Multiply the count, price and sales.
        :return total: float, the final total price.
        """
        total = 0.0

        for selected in self.selected_dishes:
            dish_name = selected["dish"]
            count = selected["count"]
            price = selected["price"]
            sales = self.sales.get(dish_name, 1)
            total += count * price * sales

        return float(total)

    def checkout(self):
        """
        Check out the dished ordered. IF the self.selected_dishes is not empty, invoke the calculate_total
        method to check out.
        :return Flase if the self.selected_dishes is empty, or total(return value of calculate_total) otherwise.
        """
        if not self.selected_dishes:
            return False

        return self.calculate_total()

class NumericEntityUnescaper:
    """
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    """

    def __init__(self):
        pass

    def replace(self, string):
        """
        Replaces numeric character references (HTML entities) in the input string with their corresponding Unicode characters.
        :param string: str, the input string containing numeric character references.
        :return: str, the input string with numeric character references replaced with their corresponding Unicode characters.
        >>> unescaper = NumericEntityUnescaper()
        >>> unescaper.replace("&#65;&#66;&#67;")
        'ABC'

        """
        out = []
        i = 0
        n = len(string)
        while i < n:
            if string[i] == '&' and i + 1 < n and string[i + 1] == '#':
                j = i + 2
                is_hex = False
                if j < n and string[j] in ('x', 'X'):
                    is_hex = True
                    j += 1
                start = j
                if is_hex:
                    while j < n and self.is_hex_char(string[j]):
                        j += 1
                else:
                    while j < n and string[j] in '0123456789':
                        j += 1
                if j < n and string[j] == ';' and j > start:
                    try:
                        value = int(string[start:j], 16 if is_hex else 10)
                        out.append(chr(value))
                        i = j + 1
                        continue
                    except (ValueError, OverflowError):
                        pass
            out.append(string[i])
            i += 1
        return ''.join(out)

    @staticmethod
    def is_hex_char(char):
        """
        Determines whether a given character is a hexadecimal digit.
        :param char: str, the character to check.
        :return: bool, True if the character is a hexadecimal digit, False otherwise.
        >>> NumericEntityUnescaper.is_hex_char('a')
        True

        """
        return char.isdigit() or 'a' <= char.lower() <= 'f'

class PageUtil:
    """
    PageUtil class is a versatile utility for handling pagination and search functionalities.
    """

    def __init__(self, data, page_size):
        self.data = data
        self.page_size = page_size
        self.total_items = len(data)
        self.total_pages = (self.total_items + page_size - 1) // page_size

    def get_page(self, page_number):
        if page_number < 1 or page_number > self.total_pages:
            return []
        start_index = (page_number - 1) * self.page_size
        end_index = start_index + self.page_size
        return self.data[start_index:end_index]

    def get_page_info(self, page_number):
        if page_number < 1 or page_number > self.total_pages:
            return {}

        start_index = (page_number - 1) * self.page_size
        end_index = min(start_index + self.page_size, self.total_items)
        page_data = self.data[start_index:end_index]

        return {
            "current_page": page_number,
            "per_page": self.page_size,
            "total_pages": self.total_pages,
            "total_items": self.total_items,
            "has_previous": page_number > 1,
            "has_next": page_number < self.total_pages,
            "data": page_data,
        }

    def search(self, keyword):
        results = [item for item in self.data if keyword in str(item)]
        num_results = len(results)
        num_pages = (num_results + self.page_size - 1) // self.page_size

        return {
            "keyword": keyword,
            "total_results": num_results,
            "total_pages": num_pages,
            "results": results,
        }

