        self.player_row = 0
        self.player_col = 0
        self.targets = []
        self.boxes = []
        self.target_count = 0
        self.is_game_over = False
        for r, row in enumerate(self.map):
            for c, ch in enumerate(row):
                if ch == 'O':
                    self.player_row = r
                    self.player_col = c
                elif ch == 'G':
                    self.targets.append((r, c))
                    self.target_count += 1
                elif ch == 'X':
                    self.boxes.append((r, c))

    def check_win(self):
        self.is_game_over = set(self.boxes) == set(self.targets)
        return self.is_game_over

    def print_map(self):
        background = []
        for row in self.map:
            new_row = []
            for ch in row:
                if ch in ('O', 'X'):
                    new_row.append(' ')
                else:
                    new_row.append(ch)
            background.append(new_row)

        for r, c in self.boxes:
            background[r][c] = 'X'
        background[self.player_row][self.player_col] = 'O'

        for row in background:
            print(' '.join(row))

    def move(self, direction):
        if self.is_game_over:
            return True

        deltas = {'w': (-1, 0), 's': (1, 0), 'a': (0, -1), 'd': (0, 1)}
        if direction not in deltas:
            return self.is_game_over

        dr, dc = deltas[direction]
        nr = self.player_row + dr
        nc = self.player_col + dc

        if not (0 <= nr < len(self.map) and 0 <= nc < len(self.map[nr])):
            return self.is_game_over
        if self.map[nr][nc] == '#':
            return self.is_game_over

        box_index = None
        for i, (br, bc) in enumerate(self.boxes):
            if br == nr and bc == nc:
                box_index = i
                break

        if box_index is not None:
            br = nr + dr
            bc = nc + dc

            if not (0 <= br < len(self.map) and 0 <= bc < len(self.map[br])):
                return self.is_game_over
            if self.map[br][bc] == '#':
                return self.is_game_over

            for j, (orow, ocol) in enumerate(self.boxes):
                if j != box_index and orow == br and ocol == bc:
                    return self.is_game_over

            self.boxes[box_index] = (br, bc)

        self.player_row = nr
        self.player_col = nc
        self.check_win()
        return self.is_game_over
