class TicTacToe:
    def __init__(self, N=3):
        self.N = N
        self.board = [[' ' for _ in range(N)] for _ in range(N)]
        self.current_player = 'X'

    def make_move(self, row, col):
        if not (0 <= row < self.N and 0 <= col < self.N):
            return False
        if self.board[row][col] != ' ':
            return False

        self.board[row][col] = self.current_player
        self.current_player = 'O' if self.current_player == 'X' else 'X'
        return True

    def check_winner(self):
        n = self.N
        board = self.board

        for i in range(n):
            if board[i][0] != ' ' and all(board[i][j] == board[i][0] for j in range(1, n)):
                return board[i][0]

        for j in range(n):
            if board[0][j] != ' ' and all(board[i][j] == board[0][j] for i in range(1, n)):
                return board[0][j]

        if board[0][0] != ' ' and all(board[i][i] == board[0][0] for i in range(1, n)):
            return board[0][0]

        if board[0][n - 1] != ' ' and all(board[i][n - 1 - i] == board[0][n - 1] for i in range(1, n)):
            return board[0][n - 1]

        return None

    def is_board_full(self):
        return all(cell != ' ' for row in self.board for cell in row)
