class BigNumCalculator:
    """
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    """

    @staticmethod
    def _parse(num):
        s = num.strip()
        if not s:
            raise ValueError("Number cannot be empty")

        sign = 1
        if s[0] == '+':
            s = s[1:]
        elif s[0] == '-':
            sign = -1
            s = s[1:]

        if not s or not s.isdigit():
            raise ValueError("Invalid number")

        s = s.lstrip('0') or '0'
        if s == '0':
            sign = 1

        return sign, s

    @staticmethod
    def _format(sign, digits):
        if digits == '0':
            return '0'
        return ('-' if sign < 0 else '') + digits

    @staticmethod
    def _compare_abs(a, b):
        if len(a) != len(b):
            return 1 if len(a) > len(b) else -1
        if a > b:
            return 1
        if a < b:
            return -1
        return 0

    @staticmethod
    def _add_abs(a, b):
        i, j = len(a) - 1, len(b) - 1
        carry = 0
        result = []

        while i >= 0 or j >= 0 or carry:
            total = carry
            if i >= 0:
                total += ord(a[i]) - ord('0')
                i -= 1
            if j >= 0:
                total += ord(b[j]) - ord('0')
                j -= 1

            result.append(chr(ord('0') + total % 10))
            carry = total // 10

        return ''.join(reversed(result)) or '0'

    @staticmethod
    def _sub_abs(a, b):
        # Assumes a >= b
        i, j = len(a) - 1, len(b) - 1
        borrow = 0
        result = []

        while i >= 0:
            digit_a = ord(a[i]) - ord('0') - borrow
            digit_b = ord(b[j]) - ord('0') if j >= 0 else 0

            if digit_a < digit_b:
                digit_a += 10
                borrow = 1
            else:
                borrow = 0

            result.append(chr(ord('0') + digit_a - digit_b))
            i -= 1
            j -= 1

        while len(result) > 1 and result[-1] == '0':
            result.pop()

        return ''.join(reversed(result)) or '0'

    @staticmethod
    def _multiply_abs(a, b):
        if a == '0' or b == '0':
            return '0'

        n, m = len(a), len(b)
        result = [0] * (n + m)

        for i in range(n - 1, -1, -1):
            ai = ord(a[i]) - ord('0')
            for j in range(m - 1, -1, -1):
                bj = ord(b[j]) - ord('0')
                result[i + j + 1] += ai * bj

        carry = 0
        for i in range(len(result) - 1, -1, -1):
            total = result[i] + carry
            result[i] = total % 10
            carry = total // 10

        digits = ''.join(chr(ord('0') + d) for d in result)
        digits = digits.lstrip('0')
        return digits or '0'

    @staticmethod
    def _negate(num):
        sign, digits = BigNumCalculator._parse(num)
        if digits == '0':
            return '0'
        return ('-' if sign > 0 else '') + digits

    @staticmethod
    def add(num1, num2):
        """
        Adds two big numbers.
        :param num1: The first number to add,str.
        :param num2: The second number to add,str.
        :return: The sum of the two numbers,str.
        >>> bigNum = BigNumCalculator()
        >>> bigNum.add("12345678901234567890", "98765432109876543210")
        '111111111011111111100'
        """
        sign1, digits1 = BigNumCalculator._parse(num1)
        sign2, digits2 = BigNumCalculator._parse(num2)

        if sign1 == sign2:
            return BigNumCalculator._format(
                sign1,
                BigNumCalculator._add_abs(digits1, digits2)
            )

        comparison = BigNumCalculator._compare_abs(digits1, digits2)
        if comparison >= 0:
            return BigNumCalculator._format(
                sign1,
                BigNumCalculator._sub_abs(digits1, digits2)
            )
        else:
            return BigNumCalculator._format(
                sign2,
                BigNumCalculator._sub_abs(digits2, digits1)
            )

    @staticmethod
    def subtract(num1, num2):
        """
        Subtracts two big numbers.
        :param num1: The first number to subtract,str.
        :param num2: The second number to subtract,str.
        :return: The difference of the two numbers,str.
        >>> bigNum = BigNumCalculator()
        >>> bigNum.subtract("12345678901234567890", "98765432109876543210")
        '-86419753208641975320'
        """
        return BigNumCalculator.add(num1, BigNumCalculator._negate(num2))

    @staticmethod
    def multiply(num1, num2):
        """
        Multiplies two big numbers.
        :param num1: The first number to multiply,str.
        :param num2: The second number to multiply,str.
        :return: The product of the two numbers,str.
        >>> bigNum = BigNumCalculator()
        >>> bigNum.multiply("12345678901234567890", "98765432109876543210")
        '1219326311370217952237463801111263526900'
        """
        sign1, digits1 = BigNumCalculator._parse(num1)
        sign2, digits2 = BigNumCalculator._parse(num2)

        return BigNumCalculator._format(
            sign1 * sign2,
            BigNumCalculator._multiply_abs(digits1, digits2)
        )
