        self.BOARD_SIZE = BOARD_SIZE
        self.ICONS = ICONS
        self.board = self.create_board()

    def create_board(self):
        rows, cols = self.BOARD_SIZE
        return [[self.ICONS[y % len(self.ICONS)] for y in range(cols)] for _ in range(rows)]

    def is_valid_move(self, pos1, pos2):
        rows, cols = self.BOARD_SIZE
        x1, y1 = pos1
        x2, y2 = pos2
        if not (0 <= x1 < rows and 0 <= y1 < cols and 0 <= x2 < rows and 0 <= y2 < cols):
            return False
        if pos1 == pos2:
            return False
        if self.board[x1][y1] == ' ' or self.board[x2][y2] == ' ':
            return False
        if self.board[x1][y1] != self.board[x2][y2]:
            return False
        return self.has_path(pos1, pos2)

    def has_path(self, pos1, pos2):
        rows, cols = self.BOARD_SIZE
        x1, y1 = pos1
        x2, y2 = pos2
        if not (0 <= x1 < rows and 0 <= y1 < cols and 0 <= x2 < rows and 0 <= y2 < cols):
            return False
        if pos1 == pos2:
            return False

        dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        queue = deque()
        queue.append((x1, y1, -1, 0))
        visited = {(x1, y1, -1): 0}

        while queue:
            x, y, d, turns = queue.popleft()
            for nd, (dx, dy) in enumerate(dirs):
                nx, ny = x + dx, y + dy
                if not (-1 <= nx <= rows and -1 <= ny <= cols):
                    continue
                if d == -1:
                    new_turns = 0
                elif nd == d:
                    new_turns = turns
                else:
                    new_turns = turns + 1
                if new_turns > 2:
                    continue
                if (nx, ny) == (x2, y2):
                    return True
                if 0 <= nx < rows and 0 <= ny < cols:
                    if self.board[nx][ny] != ' ':
                        continue
                key = (nx, ny, nd)
                if key not in visited or new_turns < visited[key]:
                    visited[key] = new_turns
                    queue.append((nx, ny, nd, new_turns))
        return False

    def remove_icons(self, pos1, pos2):
        x1, y1 = pos1
        x2, y2 = pos2
        self.board[x1][y1] = ' '
        self.board[x2][y2] = ' '

    def is_game_over(self):
        for row in self.board:
            for cell in row:
                if cell != ' ':
                    return False
        return True
