        if pos1 == pos2:
            return False
        if self.board[x1][y1] == ' ' or self.board[x2][y2] == ' ':
            return False
        if self.board[x1][y1] != self.board[x2][y2]:
            return False
        return self.has_path(pos1, pos2)

    def has_path(self, pos1, pos2):
        if pos1 == pos2:
            return False
        rows, cols = self.BOARD_SIZE
        if not (0 <= pos1[0] < rows and 0 <= pos1[1] < cols and 0 <= pos2[0] < rows and 0 <= pos2[1] < cols):
            return False

        dirs = [(-1, 0), (0, 1), (1, 0), (0, -1)]
        queue = deque()
        visited = set()

        for d in range(4):
            dx, dy = dirs[d]
            nx, ny = pos1[0] + dx, pos1[1] + dy
            if -1 <= nx <= rows and -1 <= ny <= cols:
                if (nx, ny) == pos2:
                    return True
                if 0 <= nx < rows and 0 <= ny < cols:
                    if self.board[nx][ny] != ' ':
                        continue
                state = (nx, ny, d, 0)
                if state not in visited:
                    visited.add(state)
                    queue.append(state)

        while queue:
            x, y, d, turns = queue.popleft()
            if (x, y) == pos2:
                return True
            for nd in range(4):
                if nd == d:
                    new_turns = turns
                else:
                    new_turns = turns + 1
                if new_turns > 2:
                    continue
                dx, dy = dirs[nd]
                nx, ny = x + dx, y + dy
                if not (-1 <= nx <= rows and -1 <= ny <= cols):
                    continue
                if (nx, ny) == pos2:
                    return True
                if 0 <= nx < rows and 0 <= ny < cols:
                    if self.board[nx][ny] != ' ':
                        continue
                state = (nx, ny, nd, new_turns)
                if state not in visited:
                    visited.add(state)
                    queue.append(state)
        return False

    def remove_icons(self, pos1, pos2):
        x1, y1 = pos1
        x2, y2 = pos2
        self.board[x1][y1] = ' '
        self.board[x2][y2] = ' '

