import numpy as np


class MetricsCalculator2:
    """
    The class provides to calculate Mean Reciprocal Rank (MRR) and Mean Average Precision (MAP)
    based on input data, where MRR measures the ranking quality and MAP measures the average precision.
    """

    def __init__(self):
        pass

    @staticmethod
    def _is_single_sample(data):
        if isinstance(data, (tuple, list)) and len(data) == 2:
            first, second = data
            if isinstance(second, (int, float, np.integer, np.floating)) and not isinstance(second, bool):
                if isinstance(first, (list, tuple, np.ndarray)):
                    return True
        return False

    @staticmethod
    def _normalize(data):
        if MetricsCalculator2._is_single_sample(data):
            return [data]
        return list(data)

    @staticmethod
    def mrr(data):
        """
        compute the MRR of the input data. MRR is a widely used evaluation index. It is the mean of reciprocal rank.
        :param data: the data must be a tuple, list 0,1,eg.([1,0,...],5). In each tuple
                     (actual result, ground truth num), ground truth num is the total ground num.
                     ([1,0,...],5), or list of tuple eg. [([1,0,1,...],5),([1,0,...],6),([0,0,...],5)].
                     1 stands for a correct answer, 0 stands for a wrong answer.
        :return: if input data is list, return the recall of this list. if the input data is list of list,
                 return the average recall on all list. The second return value is a list of precision for each input.
        """
        samples = MetricsCalculator2._normalize(data)
        rrs = []

        for sample in samples:
            actual, _ = sample
            actual = np.asarray(actual).ravel()

            rr = 0.0
            for i, val in enumerate(actual, start=1):
                if val == 1:
                    rr = 1.0 / i
                    break

            rrs.append(float(rr))

        if not rrs:
            return 0.0, []

        return float(np.mean(rrs)), rrs

    @staticmethod
    def map(data):
        """
        compute the MAP of the input data. MAP is a widely used evaluation index. It is the mean of AP
        (average precision).
        :param data: the data must be a tuple, list 0,1,eg.([1,0,...],5). In each tuple
                     (actual result, ground truth num), ground truth num is the total ground num.
                     ([1,0,...],5), or list of tuple eg. [([1,0,1,...],5),([1,0,...],6),([0,0,...],5)].
                     1 stands for a correct answer, 0 stands for a wrong answer.
        :return: if input data is list, return the recall of this list. if the input data is list of list,
                 return the average recall on all list. The second return value is a list of precision for each input.
        """
        samples = MetricsCalculator2._normalize(data)
        aps = []

        for sample in samples:
            actual, total = sample
            actual = np.asarray(actual).ravel()
            total = float(total)

            if total == 0:
                aps.append(0.0)
                continue

            correct = 0
            precision_sum = 0.0

            for i, val in enumerate(actual, start=1):
                if val == 1:
                    correct += 1
                    precision_sum += correct / i

            ap = precision_sum / total
            aps.append(float(ap))

        if not aps:
            return 0.0, []

        return float(np.mean(aps)), aps
