        """
        if not isinstance(data, (list, tuple)):
            raise Exception('the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple')
        if len(data) == 0:
            return (0.0, [0.0])

        def _mrr_single(sub_list, total_num):
            if total_num == 0:
                return 0.0
            for idx, value in enumerate(sub_list, 1):
                if value == 1:
                    return 1.0 / idx
            return 0.0

        if isinstance(data, tuple):
            sub_list, total_num = data
            mr = _mrr_single(sub_list, total_num)
            return (mr, [mr])
