class TriCalculator:
    def __init__(self):
        pass

    def cos(self, x):
        return round(self.taylor(x, 50), 10)

    def factorial(self, a):
        result = 1
        for i in range(2, a + 1):
            result *= i
        return result

    def taylor(self, x, n):
        x_rad = x / 180 * pi
        result = 0
        for i in range(n):
            result += ((-1) ** i) * (x_rad ** (2 * i)) / self.factorial(2 * i)
        return result

    def sin(self, x):
        return self.cos(90 - x)

    def tan(self, x):
        return round(self.sin(x) / self.cos(x), 10)
