class BigNumCalculator:
    """
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    """

    @staticmethod
    def _parse(num):
        num = num.strip()
        if not num:
            raise ValueError("Empty number string")

        sign = 1
        if num[0] == '-':
            sign = -1
            num = num[1:]
        elif num[0] == '+':
            num = num[1:]

        num = num.lstrip('0')
        if not num:
            num = '0'

        if num == '0':
            sign = 1

        return sign, num

    @staticmethod
    def _compare_abs(a, b):
        if len(a) != len(b):
            return 1 if len(a) > len(b) else -1
        if a == b:
            return 0
        return 1 if a > b else -1

    @staticmethod
    def _abs_add(a, b):
        max_length = max(len(a), len(b))
        a = a.zfill(max_length)
        b = b.zfill(max_length)

        carry = 0
        result = []

        for i in range(max_length - 1, -1, -1):
            digit_sum = int(a[i]) + int(b[i]) + carry
            carry = digit_sum // 10
            result.append(str(digit_sum % 10))

        if carry:
            result.append(str(carry))

        result.reverse()
        return ''.join(result).lstrip('0') or '0'

    @staticmethod
    def _abs_subtract(a, b):
        max_length = max(len(a), len(b))
        a = a.zfill(max_length)
        b = b.zfill(max_length)

        borrow = 0
        result = []

        for i in range(max_length - 1, -1, -1):
            digit_diff = int(a[i]) - int(b[i]) - borrow
            if digit_diff < 0:
                digit_diff += 10
                borrow = 1
            else:
                borrow = 0
            result.append(str(digit_diff))

        result.reverse()
        return ''.join(result).lstrip('0') or '0'

    @staticmethod
    def _abs_multiply(a, b):
        if a == '0' or b == '0':
            return '0'

        result = [0] * (len(a) + len(b))

        for i in range(len(a) - 1, -1, -1):
            carry = 0
            ai = int(a[i])
            for j in range(len(b) - 1, -1, -1):
                pos = i + j + 1
                total = ai * int(b[j]) + result[pos] + carry
                result[pos] = total % 10
                carry = total // 10
            result[i] += carry

        start = 0
        while start < len(result) - 1 and result[start] == 0:
            start += 1

        return ''.join(map(str, result[start:]))

    @staticmethod
    def add(num1, num2):
        """
        Adds two big numbers.
        :param num1: The first number to add,str.
        :param num2: The second number to add,str.
        :return: The sum of the two numbers,str.
        """
        sign1, a = BigNumCalculator._parse(num1)
        sign2, b = BigNumCalculator._parse(num2)

        if sign1 == sign2:
            result = BigNumCalculator._abs_add(a, b)
            if result == '0':
                return '0'
            return ('-' if sign1 < 0 else '') + result

        cmp = BigNumCalculator._compare_abs(a, b)
        if cmp == 0:
            return '0'

        if cmp > 0:
            result = BigNumCalculator._abs_subtract(a, b)
            sign = sign1
        else:
            result = BigNumCalculator._abs_subtract(b, a)
            sign = sign2

        if result == '0':
            return '0'
        return ('-' if sign < 0 else '') + result

    @staticmethod
    def subtract(num1, num2):
        """
        Subtracts two big numbers.
        :param num1: The first number to subtract,str.
        :param num2: The second number to subtract,str.
        :return: The difference of the two numbers,str.
        """
        sign2, b = BigNumCalculator._parse(num2)

        if b == '0':
            return BigNumCalculator.add(num1, '0')

        neg_num2 = ('' if sign2 < 0 else '-') + b
        return BigNumCalculator.add(num1, neg_num2)

    @staticmethod
    def multiply(num1, num2):
        """
        Multiplies two big numbers.
        :param num1: The first number to multiply,str.
        :param num2: The second number to multiply,str.
        :return: The product of the two numbers,str.
        """
        sign1, a = BigNumCalculator._parse(num1)
        sign2, b = BigNumCalculator._parse(num2)

        if a == '0' or b == '0':
            return '0'

        result = BigNumCalculator._abs_multiply(a, b)
        sign = sign1 * sign2
        return ('-' if sign < 0 else '') + result
