class PushBoxGame:
    """
    This class implements a functionality of a sokoban game, where the player needs to move boxes to designated targets in order to win.
    """

    def __init__(self, map):
        self.map = map
        self.player_row = 0
        self.player_col = 0
        self.targets = []
        self.boxes = []
        self.target_count = 0
        self.is_game_over = False
        self.init_game()

    def init_game(self):
        self.player_row = 0
        self.player_col = 0
        self.targets = []
        self.boxes = []
        self.target_count = 0
        self.is_game_over = False

        for row in range(len(self.map)):
            for col in range(len(self.map[row])):
                cell = self.map[row][col]
                if cell == 'O':
                    self.player_row = row
                    self.player_col = col
                elif cell == 'G':
                    self.targets.append((row, col))
                    self.target_count += 1
                elif cell == 'X':
                    self.boxes.append((row, col))

    def check_win(self):
        box_on_target_count = sum(1 for box in self.boxes if box in self.targets)
        self.is_game_over = (
            box_on_target_count == self.target_count
            and len(self.boxes) == self.target_count
        )
        return self.is_game_over

    def move(self, direction):
        deltas = {
            'w': (-1, 0),
            's': (1, 0),
            'a': (0, -1),
            'd': (0, 1),
        }

        if direction not in deltas:
            return self.check_win()

        dr, dc = deltas[direction]
        new_player_row = self.player_row + dr
        new_player_col = self.player_col + dc

        if not (
            0 <= new_player_row < len(self.map)
            and 0 <= new_player_col < len(self.map[new_player_row])
        ):
            return self.check_win()

        if self.map[new_player_row][new_player_col] == '#':
            return self.check_win()

        if (new_player_row, new_player_col) in self.boxes:
            new_box_row = new_player_row + dr
            new_box_col = new_player_col + dc

            if not (
                0 <= new_box_row < len(self.map)
                and 0 <= new_box_col < len(self.map[new_box_row])
            ):
                return self.check_win()

            if self.map[new_box_row][new_box_col] == '#':
                return self.check_win()

            if (new_box_row, new_box_col) in self.boxes:
                return self.check_win()

            self.boxes.remove((new_player_row, new_player_col))
            self.boxes.append((new_box_row, new_box_col))

        self.player_row = new_player_row
        self.player_col = new_player_col
        return self.check_win()

    def print_map(self):
        for row in range(len(self.map)):
            chars = []
            for col in range(len(self.map[row])):
                if self.map[row][col] == '#':
                    cell = '#'
                else:
                    cell = ' '

                if (row, col) in self.targets:
                    cell = 'G'
                if (row, col) in self.boxes:
                    cell = 'X'
                if row == self.player_row and col == self.player_col:
                    cell = 'O'

                chars.append(cell)

            print(' '.join(chars) + ' ')
