class BalancedBrackets:
    """Checks for balanced brackets in an expression."""

    def __init__(self, expr):
        self.stack = []
        self.left_brackets = ["(", "{", "["]
        self.right_brackets = [")", "}", "]"]
        self.expr = expr

    def clear_expr(self):
        """Remove all non-bracket characters from the expression."""
        self.expr = "".join(
            char
            for char in self.expr
            if char in self.left_brackets or char in self.right_brackets
        )

    def check_balanced_brackets(self):
        """Return True if the expression has balanced brackets, False otherwise."""
        self.clear_expr()
        self.stack = []
        matching = dict(zip(self.right_brackets, self.left_brackets))

        for bracket in self.expr:
            if bracket in self.left_brackets:
                self.stack.append(bracket)
            elif bracket in self.right_brackets:
                if not self.stack or self.stack.pop() != matching[bracket]:
                    return False

        return not self.stack
