class BigNumCalculator:
    """
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    """

    @staticmethod
    def _parse(num):
        num = str(num).strip()
        sign = 1
        if num.startswith('-'):
            sign = -1
            num = num[1:]
        elif num.startswith('+'):
            num = num[1:]

        num = num.lstrip('0')
        if num == '':
            num = '0'
        return sign, num

    @staticmethod
    def _add_abs(a, b):
        i, j = len(a) - 1, len(b) - 1
        carry = 0
        res = []

        while i >= 0 or j >= 0 or carry:
            total = carry
            if i >= 0:
                total += ord(a[i]) - ord('0')
                i -= 1
            if j >= 0:
                total += ord(b[j]) - ord('0')
                j -= 1

            res.append(chr(total % 10 + ord('0')))
            carry = total // 10

        return ''.join(reversed(res))

    @staticmethod
    def _sub_abs(a, b):
        i, j = len(a) - 1, len(b) - 1
        borrow = 0
        res = []

        while i >= 0:
            total = ord(a[i]) - ord('0') - borrow
            if j >= 0:
                total -= ord(b[j]) - ord('0')
                j -= 1

            if total < 0:
                total += 10
                borrow = 1
            else:
                borrow = 0

            res.append(chr(total + ord('0')))
            i -= 1

        while len(res) > 1 and res[-1] == '0':
            res.pop()

        return ''.join(reversed(res))

    @staticmethod
    def _cmp_abs(a, b):
        if len(a) != len(b):
            return 1 if len(a) > len(b) else -1
        if a == b:
            return 0
        return 1 if a > b else -1

    @staticmethod
    def add(num1, num2):
        sign1, a = BigNumCalculator._parse(num1)
        sign2, b = BigNumCalculator._parse(num2)

        if sign1 == sign2:
            s = BigNumCalculator._add_abs(a, b)
            if s == '0':
                return '0'
            return ('-' if sign1 < 0 else '') + s

        cmp = BigNumCalculator._cmp_abs(a, b)
        if cmp == 0:
            return '0'

        if cmp > 0:
            s = BigNumCalculator._sub_abs(a, b)
            return ('-' if sign1 < 0 else '') + s
        else:
            s = BigNumCalculator._sub_abs(b, a)
            return ('-' if sign2 < 0 else '') + s

    @staticmethod
    def subtract(num1, num2):
        sign2, b = BigNumCalculator._parse(num2)
        if sign2 < 0:
            neg2 = b
        else:
            neg2 = '-' + b
        return BigNumCalculator.add(num1, neg2)

    @staticmethod
    def multiply(num1, num2):
        sign1, a = BigNumCalculator._parse(num1)
        sign2, b = BigNumCalculator._parse(num2)

        if a == '0' or b == '0':
            return '0'

        n, m = len(a), len(b)
        res = [0] * (n + m)

        for i in range(n - 1, -1, -1):
            d1 = ord(a[i]) - ord('0')
            carry = 0
            for j in range(m - 1, -1, -1):
                d2 = ord(b[j]) - ord('0')
                total = d1 * d2 + res[i + j + 1] + carry
                res[i + j + 1] = total % 10
                carry = total // 10
            res[i] += carry

        start = 0
        while start < len(res) - 1 and res[start] == 0:
            start += 1

        s = ''.join(str(d) for d in res[start:])
        return ('-' if sign1 * sign2 < 0 else '') + s
