        s = str(num).strip()
        if not s:
            return 1, "0"
        sign = 1
        if s[0] == '-':
            sign = -1
            s = s[1:]
        elif s[0] == '+':
            s = s[1:]
        s = s.lstrip('0')
        if not s:
            return 1, "0"
        return sign, s

    @staticmethod
    def _add_abs(a, b):
        i, j = len(a) - 1, len(b) - 1
        carry = 0
        result = []
        while i >= 0 or j >= 0 or carry:
            da = ord(a[i]) - 48 if i >= 0 else 0
            db = ord(b[j]) - 48 if j >= 0 else 0
            total = da + db + carry
            result.append(chr(total % 10 + 48))
            carry = total // 10
            i -= 1
            j -= 1
        return ''.join(reversed(result))

    @staticmethod
    def _compare_abs(a, b):
        if len(a) != len(b):
            return -1 if len(a) < len(b) else 1
        if a == b:
            return 0
        return -1 if a < b else 1

    @staticmethod
    def _sub_abs(a, b):
        i, j = len(a) - 1, len(b) - 1
        borrow = 0
        result = []
        while i >= 0:
            da = ord(a[i]) - 48
            db = ord(b[j]) - 48 if j >= 0 else 0
            diff = da - db - borrow
            if diff < 0:
                diff += 10
                borrow = 1
            else:
                borrow = 0
            result.append(chr(diff + 48))
            i -= 1
            j -= 1
        while len(result) > 1 and result[-1] == '0':
            result.pop()
        return ''.join(reversed(result))

    @staticmethod
    def _mul_abs(a, b):
        if a == "0" or b == "0":
            return "0"
        result = [0] * (len(a) + len(b))
        for i in range(len(a) - 1, -1, -1):
            ai = ord(a[i]) - 48
            for j in range(len(b) - 1, -1, -1):
                bj = ord(b[j]) - 48
                p1 = i + j
                p2 = i + j + 1
                total = ai * bj + result[p2]
                result[p1] += total // 10
                result[p2] = total % 10
        start = 0
        while start < len(result) - 1 and result[start] == 0:
            start += 1
        return ''.join(str(d) for d in result[start:])

    @staticmethod
    def _negate(num):
        sign, digits = BigNumCalculator._parse(num)
        if digits == "0":
            return "0"
        return ("-" if sign > 0 else "") + digits

    @staticmethod
    def add(num1, num2):
        """
        Adds two big numbers.
        :param num1: The first number to add,str.
        :param num2: The second number to add,str.
        :return: The sum of the two numbers,str.
        >>> bigNum = BigNumCalculator()
        >>> bigNum.add("12345678901234567890", "98765432109876543210")
        '111111111011111111100'
        """
        sign1, a = BigNumCalculator._parse(num1)
        sign2, b = BigNumCalculator._parse(num2)

        if sign1 == sign2:
            res = BigNumCalculator._add_abs(a, b)
            if res == "0":
                return "0"
            return ("-" if sign1 < 0 else "") + res

        cmp = BigNumCalculator._compare_abs(a, b)
        if cmp == 0:
            return "0"

        if cmp > 0:
            res = BigNumCalculator._sub_abs(a, b)
            sign = sign1
        else:
            res = BigNumCalculator._sub_abs(b, a)
            sign = sign2

        if res == "0":
            return "0"
        return ("-" if sign < 0 else "") + res

    @staticmethod
    def subtract(num1, num2):
        """
        Subtracts two big numbers.
        :param num1: The first number to subtract,str.
        :param num2: The second number to subtract,str.
        :return: The difference of the two numbers,str.
        >>> bigNum = BigNumCalculator()
        >>> bigNum.subtract("12345678901234567890", "98765432109876543210")
        '-86419753208641975320'
        """
        return BigNumCalculator.add(num1, BigNumCalculator._negate(num2))

    @staticmethod
    def multiply(num1, num2):
        """
        Multiplies two big numbers.
        :param num1: The first number to multiply,str.
        :param num2: The second number to multiply,str.
        :return: The product of the two numbers,str.
        >>> bigNum = BigNumCalculator()
        >>> bigNum.multiply("12345678901234567890", "98765432109876543210")
        '1219326311370217952237463801111263526900'
        """
        sign1, a = BigNumCalculator._parse(num1)
        sign2, b = BigNumCalculator._parse(num2)

        res = BigNumCalculator._mul_abs(a, b)
        if res == "0":
            return "0"
        return ("-" if sign1 * sign2 < 0 else "") + res

