from bisect import bisect_right


class Interpolation:
    """
    This is a class that implements the Linear interpolation operation of one-dimensional and two-dimensional data
    """

    def __init__(self):
        pass

    @staticmethod
    def _find_interval(values, target):
        n = len(values)
        if n == 0:
            raise ValueError("values must not be empty")
        if n == 1:
            return 0, 0.0
        if target <= values[0]:
            return 0, (target - values[0]) / (values[1] - values[0])
        if target >= values[-1]:
            return n - 2, (target - values[-2]) / (values[-1] - values[-2])
        i = bisect_right(values, target) - 1
        return i, (target - values[i]) / (values[i + 1] - values[i])

    @staticmethod
    def interpolate_1d(x, y, x_interp):
        """
        Linear interpolation of one-dimensional data
        :param x: The x-coordinate of the data point, list.
        :param y: The y-coordinate of the data point, list.
        :param x_interp: The x-coordinate of the interpolation point, list.
        :return: The y-coordinate of the interpolation point, list.
        >>> interpolation = Interpolation()
        >>> interpolation.interpolate_1d([1, 2, 3], [1, 2, 3], [1.5, 2.5])
        [1.5, 2.5]
        """
        if len(x) != len(y):
            raise ValueError("x and y must have the same length")
        if len(x) == 0:
            raise ValueError("x and y must not be empty")
        if len(x) == 1:
            return [y[0] for _ in x_interp]

        result = []
        for xi in x_interp:
            i, t = Interpolation._find_interval(x, xi)
            yi = y[i] * (1 - t) + y[i + 1] * t
            result.append(yi)
        return result

    @staticmethod
    def interpolate_2d(x, y, z, x_interp, y_interp):
        """
        Linear interpolation of two-dimensional data
        :param x: The x-coordinate of the data point, list.
        :param y: The y-coordinate of the data point, list.
        :param z: The z-coordinate of the data point, list.
        :param x_interp: The x-coordinate of the interpolation point, list.
        :param y_interp: The y-coordinate of the interpolation point, list.
        :return: The z-coordinate of the interpolation point, list.
        >>> interpolation = Interpolation()
        >>> interpolation.interpolate_2d([1, 2, 3], [1, 2, 3], [[1, 2, 3], [4, 5, 6], [7, 8, 9]], [1.5, 2.5], [1.5, 2.5])
        [3.0, 7.0]
        """
        if len(x_interp) != len(y_interp):
            raise ValueError("x_interp and y_interp must have the same length")
        if len(x) == 0 or len(y) == 0:
            raise ValueError("x and y must not be empty")
        if len(z) != len(y):
            raise ValueError("z must have len(y) rows")
        for row in z:
            if len(row) != len(x):
                raise ValueError("z must have len(x) columns")

        result = []
        for xi, yi in zip(x_interp, y_interp):
            if len(x) == 1 and len(y) == 1:
                result.append(z[0][0])
            elif len(x) == 1:
                j, ty = Interpolation._find_interval(y, yi)
                zi = z[j][0] * (1 - ty) + z[j + 1][0] * ty
                result.append(zi)
            elif len(y) == 1:
                i, tx = Interpolation._find_interval(x, xi)
                zi = z[0][i] * (1 - tx) + z[0][i + 1] * tx
                result.append(zi)
            else:
                i, tx = Interpolation._find_interval(x, xi)
                j, ty = Interpolation._find_interval(y, yi)

                z00 = z[j][i]
                z01 = z[j][i + 1]
                z10 = z[j + 1][i]
                z11 = z[j + 1][i + 1]

                zi = (
                    z00 * (1 - tx) * (1 - ty)
                    + z01 * tx * (1 - ty)
                    + z10 * (1 - tx) * ty
                    + z11 * tx * ty
                )
                result.append(zi)

        return result
